        #start-btn { display: block; margin: 30px auto; background: linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%) !important; border: none !important; border-radius: 14px !important; padding: 18px 40px !important; font-size: 1.1rem !important; font-weight: 700 !important; color: white !important; cursor: pointer !important; box-shadow: 0 4px 20px rgba(59, 130, 246, 0.4) !important; text-transform: uppercase !important; letter-spacing: 1px !important; transition: transform 0.2s, box-shadow 0.2s; }
